package com.secure.documentwallet;

import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.fragment.app.FragmentActivity;import org.json.*;import java.util.*;import java.util.concurrent.*;

/** A private shortlist for the owner; it is not an unattended emergency-release service. */
public class EmergencyAccessActivity extends FragmentActivity {
 private final ExecutorService io=Executors.newSingleThreadExecutor();private LinearLayout list;private final Set<String> selected=new HashSet<>();
 @Override public void onCreate(Bundle b){super.onCreate(b);Ui.safeScreen(this);Ui.lightBars(this);if(!Session.valid()){finish();return;}selected.addAll(getSharedPreferences("emergency-kit",0).getStringSet("documents",Collections.emptySet()));LinearLayout page=VaultPageUi.page(this);page.addView(VaultPageUi.header(this,"Essential Documents","Your private emergency shortlist"));page.addView(VaultPageUi.notice(this,"info","Available Only After Unlock","This list helps you find critical items quickly. It does not grant access to contacts or bypass your vault lock.",0xfffff0ef,0xffc2413a));page.addView(VaultPageUi.sectionHead(this,"Included","Select important items"));list=Ui.column(this);page.addView(list);TextView save=VaultPageUi.primary(this,"Save Essential Documents");save.setBackground(Ui.bg(0xffc2413a,Ui.dp(this,13)));save.setOnClickListener(v->{getSharedPreferences("emergency-kit",0).edit().putStringSet("documents",new HashSet<>(selected)).apply();VaultActivityLog.add(this,"Essential Documents Updated",selected.size()+" protected item"+(selected.size()==1?"":"s"));Ui.toast(this,"Essential documents saved");});VaultPageUi.button(page,save);setContentView(VaultPageUi.screen(this,page,"profile"));load();}
 private void load(){io.execute(()->{try{JSONArray docs=new VaultRepository(this).all();runOnUiThread(()->render(docs));}catch(Exception e){runOnUiThread(()->Ui.toast(this,"Could Not Open Essential Documents"));}});}
 private void render(JSONArray docs){list.removeAllViews();for(int i=docs.length()-1;i>=0;i--){JSONObject doc=docs.optJSONObject(i);if(doc==null)continue;String id=doc.optString("id");CheckBox check=new CheckBox(this);check.setText(doc.optString("title","Document")+"\n"+doc.optString("category","Document"));check.setTextSize(14);check.setTextColor(Ui.INK);check.setButtonTintList(android.content.res.ColorStateList.valueOf(0xffc2413a));check.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));check.setBackground(Ui.stroke(Ui.SURFACE,Ui.dp(this,1),Ui.BORDER,Ui.dp(this,15)));check.setChecked(selected.contains(id));check.setOnCheckedChangeListener((v,on)->{if(on)selected.add(id);else selected.remove(id);});VaultPageUi.addRow(list,check);}if(docs.length()==0)list.addView(VaultPageUi.notice(this,"□","No Documents Yet","Add documents before making a shortlist",Ui.SOFT,Ui.TEAL));}
 @Override protected void onDestroy(){super.onDestroy();io.shutdownNow();}
}
